SELECT cost_bucket, shipped_year, unique_carriers, min_cost FROM (SELECT CASE WHEN cost >= 86 THEN 'high' WHEN cost >= 29 THEN 'mid' ELSE 'low' END AS cost_bucket, YEAR(shipped_date) AS shipped_year, COUNT(DISTINCT cost) AS unique_carriers, MIN(cost) AS min_cost FROM shipments WHERE shipped_date BETWEEN '2024-02-05' AND '2025-10-01' GROUP BY CASE WHEN cost >= 86 THEN 'high' WHEN cost >= 29 THEN 'mid' ELSE 'low' END, YEAR(shipped_date)) AS s WHERE unique_carriers < 9 ORDER BY min_cost DESC, shipped_year ASC;
